{
  "title": "Input schema for the youtube-search-scraper actor",
  "description": "Scrape YouTube search results using a search term, or directly input a video, channel, or results page URL. Feel free to try it out with our default settings by hitting &#9655;<b> Start</b>. If you need any help, have a read through <a href='https://blog.apify.com/how-to-scrape-youtube/' target='_blank' rel='noopener'>this tutorial</a>.",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "startUrls": {
      "title": "Direct video URLs",
      "type": "array",
      "description": "Enter a link to a specific Youtube video <a href='https://www.youtube.com/watch?v=xObhZ0Ga7EQ' target='_blank' rel='noopener'>YouTube video</a>. You can also import a CSV file or Google Sheet with a list of URLs.<br>",
      "default": [],
      "prefill": [
        {
          "url": "https://www.youtube.com/watch?v=xObhZ0Ga7EQ"
        }
      ],
      "example": [
        {
          "url": "https://www.youtube.com/watch?v=dQw4w9WgXcQ"
        }
      ],
      "editor": "requestListSources"
    },
    "maxComments": {
      "title": "Maximum comments",
      "type": "integer",
      "description": "Limit the number of comments you want to scrape per video.",
      "prefill": 10,
      "default": 1,
      "minimum": 1,
      "example": 100
    },
    "sortCommentsBy": {
      "title": "Sorting order",
      "type": "string",
      "description": "Select Youtube sorting parameter for comments",
      "editor": "select",
      "enum": [
        "TOP_COMMENTS",
        "NEWEST_FIRST"
      ],
      "enumTitles": [
        "Top comments",
        "Newest first"
      ],
      "default": "NEWEST_FIRST"
    },
    "oldestCommentDate": {
      "title": "Scrape comments published after [date]",
      "type": "string",
      "editor": "datepicker",
      "dateType": "absoluteOrRelative",
      "example": "2026-03-01",
      "pattern": "^(\\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])(T[0-2]\\d:[0-5]\\d(:[0-5]\\d)?(\\.\\d+)?Z?)?$|^(\\d+)\\s*(minute|hour|day|week|month|year)s?$",
      "description": "Only comments published after or on this date will be scraped. Alternatively, specify how old the scraped comments should be. Putting <code>1 day</code> will get you only today's comments, <code>2 days</code> - yesterday's and today's, and so on. Note, that if you select this, sorting parameter will be auto-reset to newest first"
    }
  },
  "required": [
    "startUrls"
  ]
}
